<?php
declare(strict_types=1);
/** Antialiased glyph masks, not distributable font files. */
function lc_brand_masks(): array {
    static $out=null;
    if($out!==null)return $out;
    $out=[];
    $raw=gzuncompress(base64_decode('',true));
    if(!is_string($raw)||strlen($raw)!==29192)throw new RuntimeException('Invalid graphic mask');
    $out['league']=['w'=>356,'h'=>82,'mask'=>$raw];
    $raw=gzuncompress(base64_decode('',true));
    if(!is_string($raw)||strlen($raw)!==10855)throw new RuntimeException('Invalid graphic mask');
    $out['cut']=['w'=>167,'h'=>65,'mask'=>$raw];
    $raw=gzuncompress(base64_decode('',true));
    if(!is_string($raw)||strlen($raw)!==7820)throw new RuntimeException('Invalid graphic mask');
    $out['tag']=['w'=>391,'h'=>20,'mask'=>$raw];
    return $out;
}
